-- Химус (ООО «Химус», Худжанд) -- demo database of a household / professional chemicals manufacturer in Tajikistan
-- FICTIONAL DATA generated for BI dashboard demos. Currency: TJS (somoni). Period: 2023-01-01 .. 2026-09-30.
-- No public information about the company was found: the profile (household, professional, auto and water-treatment
-- chemicals, plant in Khujand, hubs in Dushanbe and Bokhtar) is an assumption; customers, vendors, people, FX rates
-- and all numbers are invented.
-- Schema is intentionally different from fatir_agro.sql: invoices instead of orders, recipes and lots, route-based
-- shipments, stock movement ledger, price history, field-sales visits, GL entries, sales targets.
-- Safe to import into an empty MySQL 8 schema.

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
SET UNIQUE_CHECKS = 0;
SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';

DROP TABLE IF EXISTS `sales_target`;
DROP TABLE IF EXISTS `ledger_entry`;
DROP TABLE IF EXISTS `ledger_account`;
DROP TABLE IF EXISTS `stock_movement`;
DROP TABLE IF EXISTS `sales_return`;
DROP TABLE IF EXISTS `sales_visit`;
DROP TABLE IF EXISTS `shipment_stop`;
DROP TABLE IF EXISTS `shipment`;
DROP TABLE IF EXISTS `vehicle`;
DROP TABLE IF EXISTS `payment`;
DROP TABLE IF EXISTS `invoice_line`;
DROP TABLE IF EXISTS `invoice`;
DROP TABLE IF EXISTS `promo`;
DROP TABLE IF EXISTS `price_history`;
DROP TABLE IF EXISTS `customer`;
DROP TABLE IF EXISTS `downtime_event`;
DROP TABLE IF EXISTS `lab_check`;
DROP TABLE IF EXISTS `run_material_issue`;
DROP TABLE IF EXISTS `production_run`;
DROP TABLE IF EXISTS `plant_line`;
DROP TABLE IF EXISTS `purchase_order_line`;
DROP TABLE IF EXISTS `purchase_order`;
DROP TABLE IF EXISTS `fx_rate`;
DROP TABLE IF EXISTS `vendor`;
DROP TABLE IF EXISTS `formula_item`;
DROP TABLE IF EXISTS `formula`;
DROP TABLE IF EXISTS `raw_material`;
DROP TABLE IF EXISTS `certificate`;
DROP TABLE IF EXISTS `product`;
DROP TABLE IF EXISTS `product_line`;
DROP TABLE IF EXISTS `warehouse`;
DROP TABLE IF EXISTS `employee`;
DROP TABLE IF EXISTS `department`;
DROP TABLE IF EXISTS `city`;

CREATE TABLE `city` (
    `id` SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Идентификатор',
    `name` VARCHAR(60) NOT NULL COMMENT 'Название',
    `region` VARCHAR(80) NOT NULL COMMENT 'Область / регион',
    `country` VARCHAR(40) NOT NULL COMMENT 'Страна',
    `latitude` DECIMAL(9,6) NOT NULL COMMENT 'Широта',
    `longitude` DECIMAL(9,6) NOT NULL COMMENT 'Долгота',
    `route_zone` VARCHAR(24) NOT NULL COMMENT 'Маршрутная зона для формирования рейсов',
    `serving_warehouse_id` SMALLINT UNSIGNED NOT NULL COMMENT 'Склад, который обслуживает город',
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_city_name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Города и населённые пункты: география клиентов, складов и маршрутов';

CREATE TABLE `department` (
    `id` TINYINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Идентификатор',
    `code` VARCHAR(8) NOT NULL COMMENT 'Код подразделения',
    `name` VARCHAR(80) NOT NULL COMMENT 'Название',
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_department_code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Подразделения компании';

CREATE TABLE `employee` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Идентификатор',
    `full_name` VARCHAR(100) NOT NULL COMMENT 'ФИО (Фамилия Имя)',
    `gender` CHAR(1) NOT NULL COMMENT 'Пол: M / F',
    `department_id` TINYINT UNSIGNED NOT NULL COMMENT 'Подразделение',
    `job_title` VARCHAR(80) NOT NULL COMMENT 'Должность',
    `grade` TINYINT UNSIGNED NOT NULL COMMENT 'Грейд 1-6',
    `manager_id` INT UNSIGNED NULL COMMENT 'Непосредственный руководитель',
    `home_city_id` SMALLINT UNSIGNED NOT NULL COMMENT 'Город рабочего места',
    `hired_on` DATE NOT NULL COMMENT 'Дата приёма',
    `terminated_on` DATE NULL COMMENT 'Дата увольнения (NULL если работает)',
    `monthly_salary_tjs` DECIMAL(10,2) NOT NULL COMMENT 'Текущий оклад, сомони/мес',
    `work_email` VARCHAR(120) NOT NULL COMMENT 'Рабочий e-mail',
    `phone` VARCHAR(24) NOT NULL COMMENT 'Телефон',
    PRIMARY KEY (`id`),
    KEY `ix_employee_department_id` (`department_id`),
    KEY `ix_employee_job_title` (`job_title`),
    CONSTRAINT `fk_employee_department_id` FOREIGN KEY (`department_id`) REFERENCES `department` (`id`),
    CONSTRAINT `fk_employee_manager_id` FOREIGN KEY (`manager_id`) REFERENCES `employee` (`id`),
    CONSTRAINT `fk_employee_home_city_id` FOREIGN KEY (`home_city_id`) REFERENCES `city` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Сотрудники (включая торговых представителей, водителей и операторов линий)';

CREATE TABLE `warehouse` (
    `id` SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Идентификатор',
    `code` VARCHAR(10) NOT NULL COMMENT 'Код склада',
    `name` VARCHAR(100) NOT NULL COMMENT 'Название',
    `kind` VARCHAR(12) NOT NULL COMMENT 'main — центральный, hub — региональный',
    `city_id` SMALLINT UNSIGNED NOT NULL COMMENT 'Город',
    `area_m2` INT UNSIGNED NOT NULL COMMENT 'Площадь, м2',
    `capacity_pallets` INT UNSIGNED NOT NULL COMMENT 'Вместимость, паллет',
    `opened_on` DATE NOT NULL COMMENT 'Дата открытия',
    `manager_id` INT UNSIGNED NULL COMMENT 'Заведующий складом',
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_warehouse_code` (`code`),
    CONSTRAINT `fk_warehouse_city_id` FOREIGN KEY (`city_id`) REFERENCES `city` (`id`),
    CONSTRAINT `fk_warehouse_manager_id` FOREIGN KEY (`manager_id`) REFERENCES `employee` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Склады готовой продукции';

CREATE TABLE `product_line` (
    `id` TINYINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Идентификатор',
    `code` VARCHAR(16) NOT NULL COMMENT 'Код направления',
    `name` VARCHAR(100) NOT NULL COMMENT 'Название',
    `segment` VARCHAR(16) NOT NULL COMMENT 'household / professional / auto / water',
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_product_line_code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Товарные направления';

CREATE TABLE `product` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Идентификатор',
    `line_id` TINYINT UNSIGNED NOT NULL COMMENT 'Товарное направление',
    `sku` VARCHAR(16) NOT NULL COMMENT 'Артикул',
    `barcode` CHAR(13) NOT NULL COMMENT 'Штрихкод EAN-13',
    `name` VARCHAR(160) NOT NULL COMMENT 'Наименование',
    `brand` VARCHAR(30) NOT NULL COMMENT 'Бренд',
    `form` VARCHAR(12) NOT NULL COMMENT 'Форма: powder, liquid, gel, tablet, bar',
    `pack_type` VARCHAR(12) NOT NULL COMMENT 'Тип упаковки: pouch, box, bag, bottle, canister, jug, drum, pail, jar, wrap',
    `pack_size` DECIMAL(8,2) NOT NULL COMMENT 'Объём или масса упаковки',
    `pack_unit` VARCHAR(4) NOT NULL COMMENT 'Единица: kg / l',
    `net_weight_kg` DECIMAL(8,3) NOT NULL COMMENT 'Масса нетто единицы, кг',
    `gross_weight_kg` DECIMAL(8,3) NOT NULL COMMENT 'Масса брутто единицы, кг',
    `units_per_case` SMALLINT UNSIGNED NOT NULL COMMENT 'Штук в гофрокоробе',
    `hazard_class` VARCHAR(16) NOT NULL COMMENT 'none / irritant / corrosive / oxidizer / flammable',
    `shelf_life_months` TINYINT UNSIGNED NOT NULL COMMENT 'Срок годности, мес',
    `std_cost_tjs` DECIMAL(10,2) NOT NULL COMMENT 'Плановая себестоимость единицы (цены 2025 г.), сомони',
    `launched_on` DATE NOT NULL COMMENT 'Дата вывода на рынок',
    `discontinued_on` DATE NULL COMMENT 'Дата снятия с продажи',
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_product_sku` (`sku`),
    KEY `ix_product_line_id` (`line_id`),
    CONSTRAINT `fk_product_line_id` FOREIGN KEY (`line_id`) REFERENCES `product_line` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Номенклатура готовой продукции (SKU)';

CREATE TABLE `certificate` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Идентификатор',
    `product_id` INT UNSIGNED NOT NULL COMMENT 'Продукт',
    `doc_type` VARCHAR(40) NOT NULL COMMENT 'Тип документа',
    `doc_number` VARCHAR(40) NOT NULL COMMENT 'Номер',
    `issuer` VARCHAR(120) NOT NULL COMMENT 'Орган, выдавший документ',
    `issued_on` DATE NOT NULL COMMENT 'Дата выдачи',
    `valid_until` DATE NOT NULL COMMENT 'Действителен до',
    PRIMARY KEY (`id`),
    KEY `ix_certificate_valid_until` (`valid_until`),
    CONSTRAINT `fk_certificate_product_id` FOREIGN KEY (`product_id`) REFERENCES `product` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Сертификаты, декларации и санитарные заключения на продукцию';

CREATE TABLE `raw_material` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Идентификатор',
    `code` VARCHAR(12) NOT NULL COMMENT 'Код',
    `name` VARCHAR(120) NOT NULL COMMENT 'Наименование',
    `category` VARCHAR(16) NOT NULL COMMENT 'surfactant, alkali, acid, builder, bleach, active, solvent, additive, fragrance, filler, base, packaging',
    `unit` VARCHAR(4) NOT NULL COMMENT 'Единица учёта: kg или pcs',
    `base_price_usd` DECIMAL(10,4) NOT NULL COMMENT 'Ориентир цены 2025 г., USD за единицу',
    `hazard_class` VARCHAR(16) NOT NULL COMMENT 'Класс опасности',
    `moq` INT UNSIGNED NOT NULL COMMENT 'Минимальная партия закупки',
    `lot_size` INT UNSIGNED NOT NULL COMMENT 'Кратность партии (контейнер, машина)',
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_raw_material_code` (`code`),
    KEY `ix_raw_material_category` (`category`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Сырьё и упаковочные материалы';

CREATE TABLE `formula` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Идентификатор',
    `product_id` INT UNSIGNED NOT NULL COMMENT 'Продукт',
    `version` TINYINT UNSIGNED NOT NULL COMMENT 'Номер версии',
    `batch_size_kg` DECIMAL(10,2) NOT NULL COMMENT 'Стандартный размер замеса, кг',
    `valid_from` DATE NOT NULL COMMENT 'Действует с',
    `valid_to` DATE NULL COMMENT 'Действует до',
    `approved_by` INT UNSIGNED NULL COMMENT 'Технолог, утвердивший',
    PRIMARY KEY (`id`),
    KEY `ix_formula_product_id` (`product_id`),
    CONSTRAINT `fk_formula_product_id` FOREIGN KEY (`product_id`) REFERENCES `product` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Рецептуры: версия состава на продукт';

CREATE TABLE `formula_item` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Идентификатор',
    `formula_id` INT UNSIGNED NOT NULL COMMENT 'Рецептура',
    `raw_material_id` INT UNSIGNED NOT NULL COMMENT 'Сырьё',
    `share_pct` DECIMAL(7,3) NOT NULL COMMENT 'Доля в готовой продукции, % по массе',
    PRIMARY KEY (`id`),
    KEY `ix_formula_item_formula_id` (`formula_id`),
    CONSTRAINT `fk_formula_item_formula_id` FOREIGN KEY (`formula_id`) REFERENCES `formula` (`id`),
    CONSTRAINT `fk_formula_item_raw_material_id` FOREIGN KEY (`raw_material_id`) REFERENCES `raw_material` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Состав рецептуры (химические компоненты)';

CREATE TABLE `vendor` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Идентификатор',
    `name` VARCHAR(150) NOT NULL COMMENT 'Название',
    `country` VARCHAR(40) NOT NULL COMMENT 'Страна',
    `city` VARCHAR(60) NOT NULL COMMENT 'Город',
    `currency` CHAR(3) NOT NULL COMMENT 'Валюта договора',
    `main_category` VARCHAR(16) NOT NULL COMMENT 'Основная категория поставок',
    `lead_time_days` SMALLINT UNSIGNED NOT NULL COMMENT 'Типичный срок поставки, дней',
    `payment_terms_days` SMALLINT UNSIGNED NOT NULL COMMENT 'Отсрочка платежа, дней',
    `rating` DECIMAL(2,1) NOT NULL COMMENT 'Рейтинг надёжности 1-5',
    `contract_since` DATE NOT NULL COMMENT 'Работаем с',
    `is_active` TINYINT(1) NOT NULL COMMENT 'Активен',
    PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Поставщики сырья и упаковки';

CREATE TABLE `fx_rate` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Идентификатор',
    `rate_date` DATE NOT NULL COMMENT 'Дата курса',
    `currency` CHAR(3) NOT NULL COMMENT 'Валюта',
    `rate_to_tjs` DECIMAL(12,5) NOT NULL COMMENT 'Сомони за 1 единицу валюты',
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_fx_rate_rate_date_currency` (`rate_date`, `currency`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Курсы валют к сомони на 1-е число месяца (демонстрационные значения)';

CREATE TABLE `purchase_order` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Идентификатор',
    `po_number` VARCHAR(20) NOT NULL COMMENT 'Номер заказа',
    `vendor_id` INT UNSIGNED NOT NULL COMMENT 'Поставщик',
    `buyer_id` INT UNSIGNED NOT NULL COMMENT 'Закупщик',
    `ordered_on` DATE NOT NULL COMMENT 'Дата заказа',
    `expected_on` DATE NOT NULL COMMENT 'Плановая дата поставки',
    `received_on` DATE NULL COMMENT 'Фактическая дата поставки',
    `currency` CHAR(3) NOT NULL COMMENT 'Валюта заказа',
    `fx_rate_to_tjs` DECIMAL(12,5) NOT NULL COMMENT 'Курс на дату заказа',
    `incoterm` VARCHAR(8) NOT NULL COMMENT 'Условия поставки',
    `status` VARCHAR(12) NOT NULL COMMENT 'received / in_transit',
    `freight_tjs` DECIMAL(12,2) NOT NULL COMMENT 'Фрахт, сомони',
    `customs_tjs` DECIMAL(12,2) NOT NULL COMMENT 'Таможенные платежи, сомони',
    `goods_total_tjs` DECIMAL(14,2) NOT NULL COMMENT 'Стоимость товара, сомони',
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_purchase_order_po_number` (`po_number`),
    KEY `ix_purchase_order_ordered_on` (`ordered_on`),
    CONSTRAINT `fk_purchase_order_vendor_id` FOREIGN KEY (`vendor_id`) REFERENCES `vendor` (`id`),
    CONSTRAINT `fk_purchase_order_buyer_id` FOREIGN KEY (`buyer_id`) REFERENCES `employee` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Заказы поставщикам';

CREATE TABLE `purchase_order_line` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Идентификатор',
    `po_id` INT UNSIGNED NOT NULL COMMENT 'Заказ',
    `raw_material_id` INT UNSIGNED NOT NULL COMMENT 'Сырьё',
    `qty` DECIMAL(14,2) NOT NULL COMMENT 'Количество (kg или pcs)',
    `unit_price_ccy` DECIMAL(12,4) NOT NULL COMMENT 'Цена за единицу в валюте заказа',
    `line_total_tjs` DECIMAL(14,2) NOT NULL COMMENT 'Сумма строки, сомони',
    PRIMARY KEY (`id`),
    KEY `ix_purchase_order_line_po_id` (`po_id`),
    KEY `ix_purchase_order_line_raw_material_id` (`raw_material_id`),
    CONSTRAINT `fk_purchase_order_line_po_id` FOREIGN KEY (`po_id`) REFERENCES `purchase_order` (`id`),
    CONSTRAINT `fk_purchase_order_line_raw_material_id` FOREIGN KEY (`raw_material_id`) REFERENCES `raw_material` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Строки заказов поставщикам';

CREATE TABLE `plant_line` (
    `id` SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Идентификатор',
    `code` VARCHAR(10) NOT NULL COMMENT 'Код линии',
    `name` VARCHAR(120) NOT NULL COMMENT 'Название',
    `kind` VARCHAR(20) NOT NULL COMMENT 'Тип оборудования',
    `capacity_kg_per_hour` DECIMAL(9,1) NOT NULL COMMENT 'Номинальная производительность, кг/ч',
    `commissioned_on` DATE NOT NULL COMMENT 'Введена в эксплуатацию',
    `status` VARCHAR(12) NOT NULL COMMENT 'operating / maintenance',
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_plant_line_code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Производственные линии и установки';

CREATE TABLE `production_run` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Идентификатор',
    `lot_code` VARCHAR(20) NOT NULL COMMENT 'Номер партии',
    `product_id` INT UNSIGNED NOT NULL COMMENT 'Продукт',
    `plant_line_id` SMALLINT UNSIGNED NOT NULL COMMENT 'Линия',
    `formula_id` INT UNSIGNED NOT NULL COMMENT 'Рецептура',
    `started_at` DATETIME NOT NULL COMMENT 'Начало',
    `finished_at` DATETIME NOT NULL COMMENT 'Окончание',
    `shift` VARCHAR(5) NOT NULL COMMENT 'day / night',
    `operator_id` INT UNSIGNED NOT NULL COMMENT 'Оператор линии',
    `shift_lead_id` INT UNSIGNED NOT NULL COMMENT 'Начальник смены',
    `planned_kg` DECIMAL(10,2) NOT NULL COMMENT 'План, кг',
    `actual_kg` DECIMAL(10,2) NOT NULL COMMENT 'Факт, кг',
    `units_packed` INT UNSIGNED NOT NULL COMMENT 'Упаковано единиц',
    `units_rejected` INT UNSIGNED NOT NULL COMMENT 'Брак упаковки, единиц',
    `energy_kwh` DECIMAL(10,1) NOT NULL COMMENT 'Электроэнергия, кВт·ч',
    `water_m3` DECIMAL(8,2) NOT NULL COMMENT 'Вода, м3',
    `material_cost_tjs` DECIMAL(14,2) NOT NULL COMMENT 'Стоимость израсходованных материалов, сомони',
    `status` VARCHAR(12) NOT NULL COMMENT 'completed / rejected',
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_production_run_lot_code` (`lot_code`),
    KEY `ix_production_run_product_id` (`product_id`),
    KEY `ix_production_run_started_at` (`started_at`),
    CONSTRAINT `fk_production_run_product_id` FOREIGN KEY (`product_id`) REFERENCES `product` (`id`),
    CONSTRAINT `fk_production_run_plant_line_id` FOREIGN KEY (`plant_line_id`) REFERENCES `plant_line` (`id`),
    CONSTRAINT `fk_production_run_formula_id` FOREIGN KEY (`formula_id`) REFERENCES `formula` (`id`),
    CONSTRAINT `fk_production_run_operator_id` FOREIGN KEY (`operator_id`) REFERENCES `employee` (`id`),
    CONSTRAINT `fk_production_run_shift_lead_id` FOREIGN KEY (`shift_lead_id`) REFERENCES `employee` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Производственные партии (лоты)';

CREATE TABLE `run_material_issue` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Идентификатор',
    `run_id` INT UNSIGNED NOT NULL COMMENT 'Партия',
    `raw_material_id` INT UNSIGNED NOT NULL COMMENT 'Материал',
    `qty_standard` DECIMAL(12,2) NOT NULL COMMENT 'Расход по рецептуре',
    `qty_used` DECIMAL(12,2) NOT NULL COMMENT 'Фактический расход',
    `cost_tjs` DECIMAL(14,2) NOT NULL COMMENT 'Стоимость фактического расхода, сомони',
    PRIMARY KEY (`id`),
    KEY `ix_run_material_issue_run_id` (`run_id`),
    KEY `ix_run_material_issue_raw_material_id` (`raw_material_id`),
    CONSTRAINT `fk_run_material_issue_run_id` FOREIGN KEY (`run_id`) REFERENCES `production_run` (`id`),
    CONSTRAINT `fk_run_material_issue_raw_material_id` FOREIGN KEY (`raw_material_id`) REFERENCES `raw_material` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Фактический расход материалов по партиям';

CREATE TABLE `lab_check` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Идентификатор',
    `run_id` INT UNSIGNED NOT NULL COMMENT 'Партия',
    `checked_at` DATETIME NOT NULL COMMENT 'Дата и время анализа',
    `analyst_id` INT UNSIGNED NOT NULL COMMENT 'Лаборант',
    `ph` DECIMAL(4,2) NULL COMMENT 'pH (1% раствора)',
    `density_g_cm3` DECIMAL(5,3) NULL COMMENT 'Плотность, г/см3',
    `active_matter_pct` DECIMAL(5,2) NULL COMMENT 'Активное вещество (АПАВ), %',
    `viscosity_mpa_s` DECIMAL(8,1) NULL COMMENT 'Вязкость, мПа·с',
    `moisture_pct` DECIMAL(4,2) NULL COMMENT 'Влажность, %',
    `free_chlorine_pct` DECIMAL(5,2) NULL COMMENT 'Активный хлор, %',
    `alcohol_pct` DECIMAL(5,2) NULL COMMENT 'Спирт, % об.',
    `freezing_point_c` DECIMAL(5,1) NULL COMMENT 'Температура замерзания, °C',
    `verdict` VARCHAR(20) NOT NULL COMMENT 'release / release_with_note / hold / reject',
    `remarks` VARCHAR(160) NULL COMMENT 'Замечания',
    PRIMARY KEY (`id`),
    KEY `ix_lab_check_run_id` (`run_id`),
    KEY `ix_lab_check_verdict` (`verdict`),
    CONSTRAINT `fk_lab_check_run_id` FOREIGN KEY (`run_id`) REFERENCES `production_run` (`id`),
    CONSTRAINT `fk_lab_check_analyst_id` FOREIGN KEY (`analyst_id`) REFERENCES `employee` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Лабораторный контроль партий';

CREATE TABLE `downtime_event` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Идентификатор',
    `plant_line_id` SMALLINT UNSIGNED NOT NULL COMMENT 'Линия',
    `started_at` DATETIME NOT NULL COMMENT 'Начало простоя',
    `minutes` INT UNSIGNED NOT NULL COMMENT 'Длительность, минут',
    `cause` VARCHAR(24) NOT NULL COMMENT 'changeover, breakdown, no_raw_material, no_packaging, power_outage, cleaning, planned_maintenance',
    `run_id` INT UNSIGNED NULL COMMENT 'Связанная партия',
    `comment` VARCHAR(160) NULL COMMENT 'Комментарий',
    PRIMARY KEY (`id`),
    KEY `ix_downtime_event_plant_line_id` (`plant_line_id`),
    KEY `ix_downtime_event_cause` (`cause`),
    CONSTRAINT `fk_downtime_event_plant_line_id` FOREIGN KEY (`plant_line_id`) REFERENCES `plant_line` (`id`),
    CONSTRAINT `fk_downtime_event_run_id` FOREIGN KEY (`run_id`) REFERENCES `production_run` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Простои линий';

CREATE TABLE `customer` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Идентификатор',
    `name` VARCHAR(160) NOT NULL COMMENT 'Название',
    `customer_type` VARCHAR(16) NOT NULL COMMENT 'dealer, supermarket, shop, hospital, food_plant, horeca, laundry, carwash, pool, gov, export',
    `tax_id` VARCHAR(12) NULL COMMENT 'ИНН',
    `city_id` SMALLINT UNSIGNED NOT NULL COMMENT 'Город',
    `address` VARCHAR(200) NOT NULL COMMENT 'Адрес',
    `latitude` DECIMAL(9,6) NOT NULL COMMENT 'Широта',
    `longitude` DECIMAL(9,6) NOT NULL COMMENT 'Долгота',
    `contact_phone` VARCHAR(24) NOT NULL COMMENT 'Телефон',
    `contract_no` VARCHAR(24) NOT NULL COMMENT 'Номер договора',
    `contract_date` DATE NOT NULL COMMENT 'Дата договора',
    `price_tier` VARCHAR(14) NOT NULL COMMENT 'RETAIL, WHOLESALE, DEALER, INSTITUTIONAL, EXPORT',
    `payment_terms_days` SMALLINT UNSIGNED NOT NULL COMMENT 'Отсрочка платежа, дней',
    `credit_limit_tjs` DECIMAL(14,2) NOT NULL COMMENT 'Кредитный лимит, сомони',
    `sales_rep_id` INT UNSIGNED NOT NULL COMMENT 'Ответственный менеджер',
    `acquired_via` VARCHAR(20) NOT NULL COMMENT 'Канал привлечения клиента',
    `status` VARCHAR(10) NOT NULL COMMENT 'active / dormant / blocked',
    PRIMARY KEY (`id`),
    KEY `ix_customer_customer_type` (`customer_type`),
    KEY `ix_customer_city_id` (`city_id`),
    KEY `ix_customer_sales_rep_id` (`sales_rep_id`),
    CONSTRAINT `fk_customer_city_id` FOREIGN KEY (`city_id`) REFERENCES `city` (`id`),
    CONSTRAINT `fk_customer_sales_rep_id` FOREIGN KEY (`sales_rep_id`) REFERENCES `employee` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Клиенты';

CREATE TABLE `price_history` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Идентификатор',
    `product_id` INT UNSIGNED NOT NULL COMMENT 'Продукт',
    `price_tier` VARCHAR(14) NOT NULL COMMENT 'Ценовая категория',
    `valid_from` DATE NOT NULL COMMENT 'Действует с',
    `price_tjs` DECIMAL(10,2) NOT NULL COMMENT 'Цена за единицу без НДС, сомони',
    PRIMARY KEY (`id`),
    KEY `ix_price_history_product_id_price_tier_valid_from` (`product_id`, `price_tier`, `valid_from`),
    CONSTRAINT `fk_price_history_product_id` FOREIGN KEY (`product_id`) REFERENCES `product` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='История прайс-листов по ценовым категориям';

CREATE TABLE `promo` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Идентификатор',
    `name` VARCHAR(120) NOT NULL COMMENT 'Название',
    `promo_type` VARCHAR(16) NOT NULL COMMENT 'seasonal, new_launch, volume, dealer_bonus',
    `line_id` TINYINT UNSIGNED NULL COMMENT 'Товарное направление (NULL — все)',
    `customer_type` VARCHAR(16) NULL COMMENT 'Тип клиентов (NULL — все)',
    `starts_on` DATE NOT NULL COMMENT 'Начало',
    `ends_on` DATE NOT NULL COMMENT 'Окончание',
    `discount_pct` DECIMAL(5,2) NOT NULL COMMENT 'Скидка, %',
    PRIMARY KEY (`id`),
    CONSTRAINT `fk_promo_line_id` FOREIGN KEY (`line_id`) REFERENCES `product_line` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Акции и коммерческие кампании';

CREATE TABLE `invoice` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Идентификатор',
    `invoice_no` VARCHAR(20) NOT NULL COMMENT 'Номер',
    `customer_id` INT UNSIGNED NOT NULL COMMENT 'Клиент',
    `warehouse_id` SMALLINT UNSIGNED NOT NULL COMMENT 'Склад отгрузки',
    `sales_rep_id` INT UNSIGNED NOT NULL COMMENT 'Менеджер',
    `channel` VARCHAR(14) NOT NULL COMMENT 'field_visit, phone, whatsapp, telegram, b2b_portal, email, tender',
    `ordered_at` DATETIME NOT NULL COMMENT 'Дата и время заказа',
    `ship_date` DATE NULL COMMENT 'Дата отгрузки',
    `delivered_on` DATE NULL COMMENT 'Дата доставки',
    `due_date` DATE NOT NULL COMMENT 'Срок оплаты',
    `fulfilment` VARCHAR(12) NOT NULL COMMENT 'own_route, courier, pickup, export_cmr',
    `status` VARCHAR(12) NOT NULL COMMENT 'processing, shipped, delivered, cancelled',
    `cancel_reason` VARCHAR(16) NULL COMMENT 'out_of_stock, customer_request, credit_hold, duplicate',
    `gross_weight_kg` DECIMAL(12,2) NOT NULL COMMENT 'Вес брутто отгрузки, кг',
    `discount_tjs` DECIMAL(14,2) NOT NULL COMMENT 'Скидки по строкам, сомони',
    `net_tjs` DECIMAL(14,2) NOT NULL COMMENT 'Сумма без НДС, сомони',
    `vat_pct` DECIMAL(4,1) NOT NULL COMMENT 'Ставка НДС, % (демонстрационная; экспорт — 0)',
    `vat_tjs` DECIMAL(14,2) NOT NULL COMMENT 'НДС, сомони',
    `total_tjs` DECIMAL(14,2) NOT NULL COMMENT 'Итого к оплате, сомони',
    `paid_tjs` DECIMAL(14,2) NOT NULL COMMENT 'Оплачено на конец периода, сомони',
    `payment_status` VARCHAR(12) NOT NULL COMMENT 'paid, partial, open, overdue, written_off, n/a',
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_invoice_invoice_no` (`invoice_no`),
    KEY `ix_invoice_ordered_at` (`ordered_at`),
    KEY `ix_invoice_customer_id` (`customer_id`),
    KEY `ix_invoice_status` (`status`),
    KEY `ix_invoice_ship_date` (`ship_date`),
    CONSTRAINT `fk_invoice_customer_id` FOREIGN KEY (`customer_id`) REFERENCES `customer` (`id`),
    CONSTRAINT `fk_invoice_warehouse_id` FOREIGN KEY (`warehouse_id`) REFERENCES `warehouse` (`id`),
    CONSTRAINT `fk_invoice_sales_rep_id` FOREIGN KEY (`sales_rep_id`) REFERENCES `employee` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Расходные накладные (счета-фактуры) клиентам';

CREATE TABLE `invoice_line` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Идентификатор',
    `invoice_id` INT UNSIGNED NOT NULL COMMENT 'Накладная',
    `product_id` INT UNSIGNED NOT NULL COMMENT 'Продукт',
    `promo_id` INT UNSIGNED NULL COMMENT 'Применённая акция',
    `lot_run_id` INT UNSIGNED NULL COMMENT 'Основная партия отгрузки',
    `qty_ordered` INT UNSIGNED NOT NULL COMMENT 'Заказано, ед.',
    `qty_shipped` INT UNSIGNED NOT NULL COMMENT 'Отгружено, ед.',
    `list_price_tjs` DECIMAL(10,2) NOT NULL COMMENT 'Цена прайс-листа, сомони',
    `discount_pct` DECIMAL(5,2) NOT NULL COMMENT 'Итоговая скидка, %',
    `net_tjs` DECIMAL(14,2) NOT NULL COMMENT 'Сумма строки без НДС, сомони',
    `cogs_tjs` DECIMAL(14,2) NOT NULL COMMENT 'Себестоимость отгруженного, сомони',
    PRIMARY KEY (`id`),
    KEY `ix_invoice_line_invoice_id` (`invoice_id`),
    KEY `ix_invoice_line_product_id` (`product_id`),
    CONSTRAINT `fk_invoice_line_invoice_id` FOREIGN KEY (`invoice_id`) REFERENCES `invoice` (`id`),
    CONSTRAINT `fk_invoice_line_product_id` FOREIGN KEY (`product_id`) REFERENCES `product` (`id`),
    CONSTRAINT `fk_invoice_line_promo_id` FOREIGN KEY (`promo_id`) REFERENCES `promo` (`id`),
    CONSTRAINT `fk_invoice_line_lot_run_id` FOREIGN KEY (`lot_run_id`) REFERENCES `production_run` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Строки накладных';

CREATE TABLE `payment` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Идентификатор',
    `invoice_id` INT UNSIGNED NOT NULL COMMENT 'Накладная',
    `paid_on` DATE NOT NULL COMMENT 'Дата оплаты',
    `amount_tjs` DECIMAL(14,2) NOT NULL COMMENT 'Сумма, сомони',
    `method` VARCHAR(14) NOT NULL COMMENT 'bank_transfer, cash, mobile_wallet, card_terminal, offset',
    `reference_no` VARCHAR(24) NOT NULL COMMENT 'Номер платёжного документа',
    `collected_by_id` INT UNSIGNED NULL COMMENT 'Кто принял наличные',
    PRIMARY KEY (`id`),
    KEY `ix_payment_invoice_id` (`invoice_id`),
    KEY `ix_payment_paid_on` (`paid_on`),
    CONSTRAINT `fk_payment_invoice_id` FOREIGN KEY (`invoice_id`) REFERENCES `invoice` (`id`),
    CONSTRAINT `fk_payment_collected_by_id` FOREIGN KEY (`collected_by_id`) REFERENCES `employee` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Поступления денег от клиентов';

CREATE TABLE `vehicle` (
    `id` SMALLINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Идентификатор',
    `plate_no` VARCHAR(14) NOT NULL COMMENT 'Госномер',
    `make_model` VARCHAR(60) NOT NULL COMMENT 'Марка и модель',
    `capacity_kg` INT UNSIGNED NOT NULL COMMENT 'Грузоподъёмность, кг',
    `fuel_type` VARCHAR(8) NOT NULL COMMENT 'diesel / petrol',
    `fuel_l_per_100km` DECIMAL(5,1) NOT NULL COMMENT 'Расход, л/100 км',
    `base_warehouse_id` SMALLINT UNSIGNED NOT NULL COMMENT 'Базовый склад',
    `year_made` SMALLINT UNSIGNED NOT NULL COMMENT 'Год выпуска',
    `status` VARCHAR(10) NOT NULL COMMENT 'active / repair',
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_vehicle_plate_no` (`plate_no`),
    CONSTRAINT `fk_vehicle_base_warehouse_id` FOREIGN KEY (`base_warehouse_id`) REFERENCES `warehouse` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Автопарк';

CREATE TABLE `shipment` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Идентификатор',
    `route_code` VARCHAR(20) NOT NULL COMMENT 'Код рейса',
    `warehouse_id` SMALLINT UNSIGNED NOT NULL COMMENT 'Склад отправления',
    `vehicle_id` SMALLINT UNSIGNED NULL COMMENT 'Автомобиль (NULL — внешний перевозчик)',
    `driver_id` INT UNSIGNED NULL COMMENT 'Водитель',
    `carrier` VARCHAR(60) NULL COMMENT 'Внешний перевозчик',
    `route_zone` VARCHAR(24) NOT NULL COMMENT 'Маршрутная зона',
    `departed_at` DATETIME NOT NULL COMMENT 'Выезд',
    `returned_at` DATETIME NOT NULL COMMENT 'Возврат',
    `distance_km` INT UNSIGNED NOT NULL COMMENT 'Пробег, км',
    `load_kg` DECIMAL(10,1) NOT NULL COMMENT 'Загрузка, кг',
    `fuel_l` DECIMAL(8,1) NOT NULL COMMENT 'Расход топлива, л',
    `cost_tjs` DECIMAL(12,2) NOT NULL COMMENT 'Затраты на рейс, сомони',
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_shipment_route_code` (`route_code`),
    KEY `ix_shipment_departed_at` (`departed_at`),
    CONSTRAINT `fk_shipment_warehouse_id` FOREIGN KEY (`warehouse_id`) REFERENCES `warehouse` (`id`),
    CONSTRAINT `fk_shipment_vehicle_id` FOREIGN KEY (`vehicle_id`) REFERENCES `vehicle` (`id`),
    CONSTRAINT `fk_shipment_driver_id` FOREIGN KEY (`driver_id`) REFERENCES `employee` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Рейсы доставки';

CREATE TABLE `shipment_stop` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Идентификатор',
    `shipment_id` INT UNSIGNED NOT NULL COMMENT 'Рейс',
    `invoice_id` INT UNSIGNED NOT NULL COMMENT 'Накладная',
    `stop_seq` TINYINT UNSIGNED NOT NULL COMMENT 'Порядок остановки',
    `planned_at` DATETIME NOT NULL COMMENT 'Плановое прибытие',
    `arrived_at` DATETIME NOT NULL COMMENT 'Фактическое прибытие',
    `delay_min` INT NOT NULL COMMENT 'Опоздание, минут',
    `damaged_units` SMALLINT UNSIGNED NOT NULL COMMENT 'Повреждено единиц при доставке',
    `customer_rating` TINYINT UNSIGNED NULL COMMENT 'Оценка клиента 1-5',
    PRIMARY KEY (`id`),
    KEY `ix_shipment_stop_shipment_id` (`shipment_id`),
    KEY `ix_shipment_stop_invoice_id` (`invoice_id`),
    CONSTRAINT `fk_shipment_stop_shipment_id` FOREIGN KEY (`shipment_id`) REFERENCES `shipment` (`id`),
    CONSTRAINT `fk_shipment_stop_invoice_id` FOREIGN KEY (`invoice_id`) REFERENCES `invoice` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Точки выгрузки в рейсе';

CREATE TABLE `sales_visit` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Идентификатор',
    `rep_id` INT UNSIGNED NOT NULL COMMENT 'Торговый представитель',
    `customer_id` INT UNSIGNED NOT NULL COMMENT 'Клиент',
    `visited_at` DATETIME NOT NULL COMMENT 'Время визита',
    `duration_min` SMALLINT UNSIGNED NOT NULL COMMENT 'Длительность, минут',
    `purpose` VARCHAR(20) NOT NULL COMMENT 'order, payment_collection, merchandising, complaint, prospecting',
    `outcome` VARCHAR(20) NOT NULL COMMENT 'order_taken, no_order, payment_received, callback_promised',
    `invoice_id` INT UNSIGNED NULL COMMENT 'Оформленная накладная',
    `gps_distance_m` SMALLINT UNSIGNED NOT NULL COMMENT 'Расстояние от торговой точки по GPS, м',
    PRIMARY KEY (`id`),
    KEY `ix_sales_visit_rep_id` (`rep_id`),
    KEY `ix_sales_visit_visited_at` (`visited_at`),
    KEY `ix_sales_visit_customer_id` (`customer_id`),
    CONSTRAINT `fk_sales_visit_rep_id` FOREIGN KEY (`rep_id`) REFERENCES `employee` (`id`),
    CONSTRAINT `fk_sales_visit_customer_id` FOREIGN KEY (`customer_id`) REFERENCES `customer` (`id`),
    CONSTRAINT `fk_sales_visit_invoice_id` FOREIGN KEY (`invoice_id`) REFERENCES `invoice` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Визиты торговых представителей';

CREATE TABLE `sales_return` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Идентификатор',
    `invoice_line_id` INT UNSIGNED NOT NULL COMMENT 'Строка накладной',
    `returned_on` DATE NOT NULL COMMENT 'Дата возврата',
    `qty_units` INT UNSIGNED NOT NULL COMMENT 'Количество, ед.',
    `reason` VARCHAR(24) NOT NULL COMMENT 'damaged_in_transit, leak, expired, quality_complaint, wrong_item, customer_changed_mind',
    `accepted` TINYINT(1) NOT NULL COMMENT 'Принят ли возврат',
    `restocked` TINYINT(1) NOT NULL COMMENT 'Возвращён на склад',
    `credit_note_tjs` DECIMAL(12,2) NOT NULL COMMENT 'Кредит-нота, сомони',
    PRIMARY KEY (`id`),
    KEY `ix_sales_return_returned_on` (`returned_on`),
    KEY `ix_sales_return_reason` (`reason`),
    CONSTRAINT `fk_sales_return_invoice_line_id` FOREIGN KEY (`invoice_line_id`) REFERENCES `invoice_line` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Возвраты и рекламации по отгруженному товару';

CREATE TABLE `stock_movement` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Идентификатор',
    `moved_on` DATE NOT NULL COMMENT 'Дата движения',
    `warehouse_id` SMALLINT UNSIGNED NOT NULL COMMENT 'Склад',
    `product_id` INT UNSIGNED NOT NULL COMMENT 'Продукт',
    `movement_type` VARCHAR(18) NOT NULL COMMENT 'opening, production_receipt, sale_issue, return_receipt, transfer_out, transfer_in, write_off',
    `qty_units` INT NOT NULL COMMENT 'Количество, ед. (+ приход, - расход)',
    `run_id` INT UNSIGNED NULL COMMENT 'Партия',
    `invoice_id` INT UNSIGNED NULL COMMENT 'Накладная',
    `counterpart_warehouse_id` SMALLINT UNSIGNED NULL COMMENT 'Встречный склад (для перемещений)',
    `note` VARCHAR(40) NULL COMMENT 'Причина / примечание',
    PRIMARY KEY (`id`),
    KEY `ix_stock_movement_warehouse_id_product_id_moved_on` (`warehouse_id`, `product_id`, `moved_on`),
    KEY `ix_stock_movement_movement_type` (`movement_type`),
    CONSTRAINT `fk_stock_movement_warehouse_id` FOREIGN KEY (`warehouse_id`) REFERENCES `warehouse` (`id`),
    CONSTRAINT `fk_stock_movement_product_id` FOREIGN KEY (`product_id`) REFERENCES `product` (`id`),
    CONSTRAINT `fk_stock_movement_run_id` FOREIGN KEY (`run_id`) REFERENCES `production_run` (`id`),
    CONSTRAINT `fk_stock_movement_invoice_id` FOREIGN KEY (`invoice_id`) REFERENCES `invoice` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Журнал движения готовой продукции по складам (qty со знаком)';

CREATE TABLE `ledger_account` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Идентификатор',
    `code` VARCHAR(6) NOT NULL COMMENT 'Код счёта',
    `name` VARCHAR(100) NOT NULL COMMENT 'Название',
    `category` VARCHAR(16) NOT NULL COMMENT 'payroll, utilities, maintenance, logistics, marketing, admin, finance, tax, depreciation',
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_ledger_account_code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='План счетов операционных расходов';

CREATE TABLE `ledger_entry` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Идентификатор',
    `period` DATE NOT NULL COMMENT 'Период (1-е число месяца)',
    `account_id` INT UNSIGNED NOT NULL COMMENT 'Счёт',
    `department_id` TINYINT UNSIGNED NOT NULL COMMENT 'Центр затрат',
    `amount_tjs` DECIMAL(14,2) NOT NULL COMMENT 'Сумма, сомони',
    `memo` VARCHAR(120) NULL COMMENT 'Комментарий',
    PRIMARY KEY (`id`),
    KEY `ix_ledger_entry_period` (`period`),
    KEY `ix_ledger_entry_account_id` (`account_id`),
    CONSTRAINT `fk_ledger_entry_account_id` FOREIGN KEY (`account_id`) REFERENCES `ledger_account` (`id`),
    CONSTRAINT `fk_ledger_entry_department_id` FOREIGN KEY (`department_id`) REFERENCES `department` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Ежемесячные проводки по операционным расходам';

CREATE TABLE `sales_target` (
    `id` INT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'Идентификатор',
    `rep_id` INT UNSIGNED NOT NULL COMMENT 'Менеджер',
    `period` DATE NOT NULL COMMENT 'Месяц (1-е число)',
    `target_net_tjs` DECIMAL(14,2) NOT NULL COMMENT 'План продаж без НДС, сомони',
    PRIMARY KEY (`id`),
    UNIQUE KEY `uq_sales_target_rep_id_period` (`rep_id`, `period`),
    CONSTRAINT `fk_sales_target_rep_id` FOREIGN KEY (`rep_id`) REFERENCES `employee` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Ежемесячные планы продаж по менеджерам';

